# Generated by GitHub Copilot - Oct-05-2026
def candidate(mid, start=0, end=60, text="Historia da carreira musical.", ids=None):
    """Build a compact deterministic candidate with explicit observed components."""
    return {"moment_id": mid, "ideal_start": start, "ideal_end": end,
            "core_moment": {"start": start, "end": end, "text": text},
            "evidence_segment_ids": ids or ["S1"], "standalone_score": .8, "hook_score": .7,
            "clean_opening": True, "clean_ending": True, "duration_suitability_score": 1,
            "context_requirement": "none", **classify_content(text,ids or ["S1"])}


# Generated by GitHub Copilot - Oct-05-2026
def test_ads_are_penalized_but_brand_discussion_is_not():
    """Default ranking excludes a sales read, not ordinary noncommercial interviews."""
    ad = rank_candidate(candidate("AD", text="Compre na loja por apenas R$ 99. Aproveite o cupom e desconto!"))
    interview = rank_candidate(candidate("INTERVIEW", text="A carreira musical mudou depois da gravacao do album."))
    assert ad["content_type"] == "advertisement"
    assert ad["penalties"]["commercial"] > 0 and not ad["default_shortlist_eligible"]
    assert interview["penalties"]["commercial"] == 0 and interview["default_shortlist_eligible"]
    assert interview["score_components"]["audio_quality"] is None
    assert ad["editorial_score_final"] < interview["editorial_score_final"]


