def test_exact_duplicate_keeps_stronger_primary_and_alternate():
    """Preserve source IDs and evidence while collapsing identical intervals."""
    first, second = rank_candidate(candidate("M1")), rank_candidate(candidate("M2"))
    second["editorial_score_final"] = 1.0
    result, metrics = deduplicate_candidates([first, second])
    assert len(result) == 1 and result[0]["moment_id"] == "M2"
    assert result[0]["alternates"][0]["moment_id"] == "M1"
    assert metrics["exact_duplicate_count"] == 1


