def test_semantic_has_one_repair_and_honest_fallback(tmp_path, monkeypatch):
    """Failed repairs remain visible in denominator and fallback metrics."""
    from ldporto import semantic
    ctx, transcript = semantic_context(tmp_path, monkeypatch)
    invalid = model_fixture()
    invalid["topics"][0]["segment_ids"] = ["BAD"]
    calls = {"initial": 0, "repair": 0}
    def initial(*args):
        """Return one invalid model response."""
        calls["initial"] += 1
        return invalid, {}
    def repair(*args):
        """Return an invalid repair to exercise fallback accounting."""
        calls["repair"] += 1
        return invalid, {}
    monkeypatch.setattr(semantic, "call_ollama", initial)
    monkeypatch.setattr(semantic, "repair_ollama_output", repair)
    result = semantic.SemanticEngine().run(ctx, transcript)["data"]
    assert calls == {"initial": 1, "repair": 1}
    assert result["semantic_metrics"]["semantic_fallback_ratio"] == 1
    assert result["ollama_calls"][0]["repair_attempted"] and not result["ollama_calls"][0]["repair_success"]


