def test_semantic_cache_resume_and_corruption_recompute(tmp_path, monkeypatch):
    """Checksummed chunks resume deterministically and corrupted chunks recompute."""
    from ldporto import semantic
    from ldporto.core import write_json
    ctx, transcript = semantic_context(tmp_path, monkeypatch)
    calls = []
    monkeypatch.setattr(semantic, "call_ollama", lambda *args: (calls.append(True) or model_fixture(), {}))
    first = semantic.SemanticEngine().run(ctx, transcript)["data"]
    second = semantic.SemanticEngine().run(ctx, transcript)["data"]
    assert len(calls) == 1 and first["moments"] == second["moments"]
    assert second["semantic_metrics"]["semantic_cache_hit_ratio"] == 1
    cache = next((ctx.cache / "semantic_chunks").glob("*.json"))
    write_json(cache, {"version": "4.2", "key": "corrupted", "data": {}})
    third = semantic.SemanticEngine().run(ctx, transcript)["data"]
    assert len(calls) == 2 and third["moments"] == first["moments"]


